import {money} from './core.js';

export function plannerMode(goal){return goal==='retirement'?'retirement':goal==='goal'?'savings':'growth'}
export function plannerDefaults(answers){const age=Number(answers.age)||35;return {mode:plannerMode(answers.goal),age,lump:Number(answers.lump)||0,monthly:Number(answers.monthly??1000),years:Number(answers.horizon)||20,ret:10,inc:5,target:250000,savings:0,retireAge:Math.max(65,age+5),endAge:Math.max(90,age+25),income:15000,postRet:10,incomeInc:5}}
// Monthly payments in advance; annual contribution escalation on each anniversary.
export function planProject({lump,monthly,years,ret,inc}){let value=lump,paid=lump,c=monthly;const rate=(1+ret/100)**(1/12)-1,points=[{year:0,value,paid}];for(let y=1;y<=years;y++){for(let m=0;m<12;m++){value=(value+c)*(1+rate);paid+=c}points.push({year:y,value,paid});c*=1+inc/100}return {value,paid,points}}
export function monthlyNeeded(p,target){const base=planProject({...p,monthly:0}).value;if(base>=target)return 0;const factor=planProject({...p,lump:0,monthly:1}).value;return Math.max(0,(target-base)/factor)}
// Capital required for monthly income in advance, escalating annually.
export function incomeFactor(ret,increase,years){if(years<=0)return 0;const i=ret/100,g=increase/100,j=(1+i)**(1/12)-1,due=j===0?12:(1-(1+j)**-12)/(1-(1+j)**-1),ratio=(1+g)/(1+i);return due*(Math.abs(ratio-1)<1e-12?years:(1-ratio**years)/(1-ratio))}
export function plannerResult(p){
 const bounds={age:[16,100],lump:[0,100000000],monthly:[0,1000000],ret:[-20,20],inc:[0,20]};
 if(!['growth','savings','retirement'].includes(p.mode))throw Error('Choose an investment goal first.');
 if(p.mode==='retirement')Object.assign(bounds,{savings:[0,100000000],retireAge:[18,110],endAge:[19,120],income:[1,1000000],postRet:[-10,20],incomeInc:[0,20]});else Object.assign(bounds,{years:[1,60],...(p.mode==='savings'?{target:[1,1000000000]}:{})});
 for(const [key,[min,max]] of Object.entries(bounds))if(!Number.isFinite(p[key])||p[key]<min||p[key]>max)throw Error('Check your amounts and assumptions. Please stay within the limits shown.');
 let years=p.years,opening=p.lump,target=p.mode==='savings'?p.target:null,factor=null;
 if(p.mode==='retirement'){
  if(!Number.isInteger(p.retireAge)||!Number.isInteger(p.endAge)||p.retireAge<=p.age||p.endAge<=p.retireAge)throw Error('Your retirement age must be after your current age, and the income must last beyond retirement.');
  years=p.retireAge-p.age;if(years>60)throw Error('Choose a retirement date within the next 60 years.');
  opening+=p.savings;factor=incomeFactor(p.postRet,p.incomeInc,p.endAge-p.retireAge);target=p.income*factor;
 }
 if(!Number.isInteger(years))throw Error('Use whole years for your timeframe.');
 const projection=planProject({...p,lump:opening,years}),required=target===null?null:monthlyNeeded({...p,lump:opening,years},target);
 return {projection,years,target,required,supportedIncome:factor?projection.value/factor:null,shortfall:target===null?0:Math.max(0,target-projection.value)};
}
const num=(key,label,value,min,max,step=1,hint='')=>`<label class="field">${label}<input name="${key}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required inputmode="decimal">${hint?`<small>${hint}</small>`:''}</label>`;
export function plannerView(p,total){const retirement=p.mode==='retirement',savings=p.mode==='savings';return `<div class="flow planner-flow"><div class="flow-top"><a href="#home">← Home</a><span>BUILD YOUR PLAN · 3 OF ${total}</span></div><div class="progress" role="progressbar" aria-label="Profile progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="3"><span style="width:${3/total*100}%"></span></div><div class="planner-heading"><p class="eyebrow">${retirement?'YOUR RETIREMENT, IN NUMBERS':savings?'GIVE YOUR GOAL A PLAN':'SEE WHAT YOU COULD BUILD'}</p><h1>${retirement?'Plan for the income you want.':savings?'What will it take to reach your goal?':'See your money’s potential.'}</h1><p>${retirement?'Explore how much to set aside for your retirement.':savings?'Set your target, explore the numbers, then choose a monthly amount.':'Try an initial lump sum, a monthly contribution, or both.'} You can change the assumptions.</p></div><form id="planner-form"><div class="planner-layout"><section class="planner-inputs card">${savings?num('target','What is your savings goal? (R)',p.target,1,1000000000,1,'The amount you want at your goal date.'):''}${retirement?num('retireAge','Age you want to retire',p.retireAge,p.age+1,110)+num('income','Monthly income when you retire (R)',p.income,1,1000000,1,'Before tax, in rands at your retirement date.')+num('savings','Already saved for retirement (R)',p.savings,0,100000000,1,'Existing retirement savings; this is not a new payment.'):num('years','Years to invest',p.years,1,60)}${num('lump','Initial lump sum amount (R)',p.lump,0,100000000,1,'A new once-off amount. Enter 0 if you’re investing monthly only.')}${num('monthly','Your monthly contribution (R)',p.monthly,0,1000000)}<details class="planner-assumptions"><summary>Change growth & annual increases</summary><div class="fields">${num('ret',retirement?'Growth before retirement, after fees (% a year)':'Growth after all fees (% a year)',p.ret,-20,20,.1)}${num('inc','Yearly contribution increase (%)',p.inc,0,20,.1)}${retirement?num('endAge','Plan for income until age',p.endAge,p.retireAge+1,120)+num('postRet','Growth in retirement, after fees (% a year)',p.postRet,-10,20,.1)+num('incomeInc','Yearly retirement income increase (%)',p.incomeInc,0,20,.1):''}</div></details><button class="button secondary" type="submit">Update my plan ↗</button><p class="planner-simple">An estimate helps you plan. You choose the contribution that works for you.</p></section><section class="planner-output" aria-label="Your planning illustration"><div id="planner-results"></div></section></div><p id="planner-error" class="error" role="alert"></p><div class="flow-actions planner-actions"><button type="button" id="planner-back" class="text-button">← Back</button><button type="button" id="planner-continue" class="button">Use my contribution & continue →</button></div><p class="planner-bottom">Your chosen contribution and timeframe will carry into your investment matches. We’ll match the fund after your risk profile.</p></form><p id="planner-status" class="sr-only" aria-live="polite"></p></div>`}
export function plannerOutput(p,r,chart){const retirement=p.mode==='retirement',isGoal=r.target!==null,rounded=r.required===null?0:Math.ceil(r.required),ratio=isGoal?Math.min(100,r.projection.value/r.target*100):0;return `<div class="planner-result-top"><p class="eyebrow">${isGoal?'STARTING MONTHLY AMOUNT TO REACH YOUR TARGET':'ILLUSTRATED VALUE IN '+r.years+' YEARS'}</p><strong>${money(isGoal?rounded:r.projection.value)}</strong><p>${isGoal?(rounded?'per month to start, increasing by '+p.inc+'% each year':'Your starting savings could cover this target under these assumptions.'):'from your chosen contributions, after assumed fees'}</p>${isGoal&&rounded<=1000000?`<button type="button" id="use-estimate" class="button acid">Use ${money(rounded)} a month ↗</button>`:''}</div><div class="planner-chart"><div class="planner-chart-heading"><h2>Your current plan</h2><span>${money(p.monthly)} a month · ${p.inc}% yearly increase</span></div>${chart(r.projection,{id:'journey-plan'})}<div class="planner-totals"><div><span>${retirement?'Existing savings + contributions':'Total contributions'}</span><b>${money(r.projection.paid)}</b></div><div><span>Illustrated value${retirement?' at age '+p.retireAge:''}</span><b>${money(r.projection.value)}</b></div></div>${isGoal?`<div class="planner-target"><div><span>${retirement?'Capital needed for your income plan':'Your savings target'}</span><b>${money(r.target)}</b></div><div class="planner-meter" role="progressbar" aria-label="Illustrated progress towards target" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(ratio)}"><span style="width:${ratio}%"></span></div><p>${retirement?`Could support ${money(r.supportedIncome)} a month at retirement, towards your ${money(p.income)} target.`:r.shortfall>0?`${money(r.shortfall)} more needed to reach your target under these assumptions.`:'Your chosen amount could reach your target under these assumptions.'}</p></div>`:''}<p class="planner-note">Assumes ${p.ret}% growth a year after all fees and ${p.inc}% yearly contribution increases. Monthly payments are invested at the start of each month. These are planning assumptions, not a fund forecast. Actual returns can be lower or negative.</p><details><summary>How to read this plan</summary><div class="detail-body"><p>Figures are future rand amounts, before personal or policy tax. The growth rate should include all fund, platform and provider costs; we don’t deduct them again here. Account limits and access rules are checked later. This growth illustration can help you explore discretionary investments or endowments; it doesn’t model endowment tax or policy restrictions.</p>${retirement?`<p>Income starts at age ${p.retireAge} and rises by ${p.incomeInc}% each year until age ${p.endAge}, assuming ${p.postRet}% yearly growth after all fees. Income is drawn at the start of each month. The target uses the full savings balance for income, with no cash withdrawal or inheritance reserve. It aims to use the capital by the final age; it does not promise lifelong income.</p>`:''}<p>The annual contribution increase is a planning assumption. It won’t automatically change a debit order. Review your amount and provider terms before applying.</p></div></details></div>`}
export function bindPlanner(root,p,chart,{back,change,continuePlan}){
 const form=root.querySelector('#planner-form'),error=root.querySelector('#planner-error');
 const read=()=>{const next={...p};for(const el of form.querySelectorAll('input'))next[el.name]=el.value.trim()===''?NaN:Number(el.value);return next};
 const update=(validate=true)=>{try{if(validate&&!form.reportValidity())return null;const next=read(),r=plannerResult(next);Object.assign(p,next);change({...p});root.querySelector('#planner-results').innerHTML=plannerOutput(p,r,chart);error.textContent='';root.querySelector('#planner-status').textContent='Plan updated. Illustrated value '+money(r.projection.value)+'.';const use=root.querySelector('#use-estimate');if(use)use.onclick=()=>{const latest=update();if(!latest)return;const amount=Math.ceil(latest.required);if(amount>1000000){error.textContent='The estimated amount is above this calculator’s monthly limit. Try a longer timeframe or a lower target.';return}form.querySelector('[name="monthly"]').value=String(amount);update(false)};return r}catch(e){error.textContent=e.message;root.querySelector('#planner-status').textContent='Check the highlighted plan details.';return null}};
 form.onsubmit=e=>{e.preventDefault();update()};root.querySelector('#planner-back').onclick=()=>{change(read());back()};root.querySelector('#planner-continue').onclick=()=>{const r=update();if(!r)return;if(p.monthly===0&&p.lump===0){error.textContent='Choose a monthly contribution or a new initial lump sum to start an investment.';return}continuePlan({...p},r)};update(false);
}
